// ── CAMMY AI COMPANION ──
var cammyOpened = false;
var cammyHistory = [];

// ── REAL VOICE (MP3) — plays on greeting only ──
var CAMMY_VOICES = {
  greeting: 'data:audio/mpeg;base64,',
  streak3: 'data:audio/mpeg;base64,',
  streak5: 'data:audio/mpeg;base64,',
  streak10: 'data:audio/mpeg;base64,',
  badge: 'data:audio/mpeg;base64,',
  levelup: 'data:audio/mpeg;base64,',
};
function playCammyVoice(key) {
  try {
    var src = CAMMY_VOICES[key || 'greeting'];
    if (!src) return;
    if (window._cammyAudio) { window._cammyAudio.pause(); window._cammyAudio = null; }
    window._cammyAudio = new Audio(src);
    window._cammyAudio.volume = 0.9;
    window._cammyAudio.play().catch(function(){});
  } catch(e) {}
}

// ── POPUP CARD ──
function showCammyPopup(text, avatarEmoji) {
  var popup = document.getElementById('cammy-popup');
  var popupText = document.getElementById('cammy-popup-text');
  var lvlNum = document.getElementById('cp-lvl-num');
  if (!popup || !popupText) return;
  // Update level display
  if (lvlNum) lvlNum.textContent = ST.lv || 1;
  // Typewriter effect
  popupText.textContent = '';
  popup.style.display = 'block';
  popup.style.animation = 'none';
  popup.offsetHeight;
  popup.style.animation = 'popupIn .45s cubic-bezier(.22,.9,.36,1)';
  clearTimeout(window._cammyPopupTimer);
  // Type the text character by character
  var i = 0;
  var speed = 28; // ms per character
  clearInterval(window._cammyTypeTimer);
  window._cammyTypeTimer = setInterval(function() {
    if (i < text.length) {
      popupText.textContent += text[i];
      i++;
    } else {
      clearInterval(window._cammyTypeTimer);
      // Auto hide after 5s once typing done
      window._cammyPopupTimer = setTimeout(hideCammyPopup, 5000);
    }
  }, speed);
}

function hideCammyPopup() {
  clearInterval(window._cammyTypeTimer);
  clearTimeout(window._cammyPopupTimer);
  var popup = document.getElementById('cammy-popup');
  if (!popup || popup.style.display === 'none') return;
  popup.style.animation = 'popupOut .35s ease forwards';
  setTimeout(function(){
    popup.style.display = 'none';
    popup.style.animation = '';
  }, 350);
}

// ── ACHIEVEMENT POPUPS (no TTS, no speech — just visual popup) ──
var CAMMY_LINES = {
  streak3:  ["Yesss! Three in a row! You're on fire! 🔥", "Three correct! Keep going! 💪"],
  streak5:  ["FIVE STREAK! You're unstoppable right now! 🔥🔥", "Five in a row! I'm cheering for you! 🎉"],
  streak10: ["TEN STREAK!! You're an absolute LEGEND! 👑", "TEN IN A ROW! You're the best student I've had! 🏆"],
  badge:    ["New BADGE unlocked! You earned that! 🏅", "Badge collected! Look at you go! 🎖️"],
  levelup:  ["LEVEL UP!! You're amazing! 🚀", "You levelled up! Keep climbing! ⭐"],
};

function cammySay(category) {
  var lines = CAMMY_LINES[category];
  if (!lines) return;
  var line = lines[Math.floor(Math.random() * lines.length)];
  var emojiMap = {streak3:'🔥', streak5:'🔥🔥', streak10:'👑', badge:'🏅', levelup:'🚀'};
  showCammyPopup(line, emojiMap[category] || '✨');
  // Play the matching voice
  var voiceKey = category; // keys match: streak3, streak5, streak10, badge, levelup
  setTimeout(function(){ playCammyVoice(voiceKey); }, 200);
}

// hooks called from main JS
function onCammyStreak(n) {
  if (n === 10) cammySay('streak10');
  else if (n === 5) cammySay('streak5');
  else if (n === 3) cammySay('streak3');
}
function onCammyCorrect() {}  // silent — no popup for every correct answer
function onCammyWrong()   {}  // silent
function onCammyBadge()   { cammySay('badge'); }
function onCammyLevelUp() { cammySay('levelup'); }

// ── CHAT MESSAGES ──
function addCammyMsg(text, type, spontaneous) {
  var win = document.getElementById('nova-win');
  var msgs = document.getElementById('nova-msgs');
  if (!msgs) return;
  if (spontaneous && win && !win.classList.contains('open')) return;
  var div = document.createElement('div');
  div.className = 'nmsg ' + type;
  if (type === 'bot') {
    var sender = document.createElement('div');
    sender.className = 'nova-sender';
    sender.textContent = 'CAMMY ✦';
    div.appendChild(sender);
    var txt = document.createElement('div');
    txt.innerHTML = text.replace(/\n/g,'<br>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>');
    div.appendChild(txt);
  } else {
    div.textContent = text;
  }
  msgs.appendChild(div);
  msgs.scrollTop = msgs.scrollHeight;
}

function addNovaMsg(text, type) { addCammyMsg(text, type, false); }

function showTyping() {
  var msgs = document.getElementById('nova-msgs');
  if (!msgs) return;
  var div = document.createElement('div');
  div.className = 'nmsg bot'; div.id = 'nova-typing';
  var sender = document.createElement('div');
  sender.className = 'nova-sender'; sender.textContent = 'CAMMY ✦';
  div.appendChild(sender);
  var dots = document.createElement('div');
  dots.className = 'typing-dots';
  dots.innerHTML = '<span></span><span></span><span></span>';
  div.appendChild(dots);
  msgs.appendChild(div);
  msgs.scrollTop = msgs.scrollHeight;
}
function hideTyping() { var t=document.getElementById('nova-typing'); if(t) t.remove(); }

// ── GEMINI API KEY — Replace with your new key after revoking the old one ──
var GEMINI_API_KEY = sessionStorage.getItem('GEMINI_API_KEY') || "YOUR_GEMINI_API_KEY_HERE";
var GEMINI_MODEL = "gemini-3.1-flash-lite";
// ── CUSTOM API KEY MODAL ──
function promptForApiKey() {
  return new Promise((resolve) => {
    if (!document.getElementById('cammy-api-modal-styles')) {
      var style = document.createElement('style');
      style.id = 'cammy-api-modal-styles';
      style.innerHTML = `
        .cammy-api-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.85); backdrop-filter: blur(6px); z-index: 9999; display: flex; align-items: center; justify-content: center; animation: fi 0.3s ease; }
        .cammy-api-box { background: linear-gradient(145deg, #13110a, #0f0d02); border: 1px solid rgba(201,168,76,0.4); border-radius: 12px; padding: 2rem; max-width: 400px; width: 90%; text-align: center; box-shadow: 0 0 40px rgba(201,168,76,0.15); color: var(--tm); }
        body.light .cammy-api-box { background: #ffffff; border-color: rgba(0,0,0,0.1); color: #111111; box-shadow: 0 10px 40px rgba(0,0,0,0.08); }
        .cammy-api-title { font-family: 'Cinzel Decorative', serif; color: var(--ny); margin-bottom: 0.5rem; font-size: 1.2rem; }
        .cammy-api-desc { font-size: 0.85rem; line-height: 1.6; margin-bottom: 1.5rem; color: var(--td); }
        .cammy-api-link { color: #61dafb; text-decoration: underline; font-weight: bold; }
        body.light .cammy-api-link { color: #006080; }
        .cammy-api-input { width: 100%; padding: 0.8rem 1rem; background: rgba(201,168,76,0.06); border: 1px solid rgba(201,168,76,0.4); border-radius: 8px; color: var(--tm); font-family: monospace; font-size: 0.9rem; outline: none; margin-bottom: 1.5rem; transition: border-color 0.2s; box-sizing: border-box; }
        .cammy-api-input:focus { border-color: var(--nc); }
        .cammy-api-btn-row { display: flex; gap: 1rem; justify-content: center; }
        .cammy-api-cancel { padding: 0.6rem 1.2rem; background: none; border: 1px solid rgba(201,168,76,0.3); color: var(--td); border-radius: 6px; cursor: pointer; font-family: 'Cinzel', serif; font-size: 0.75rem; transition: all 0.2s; }
        .cammy-api-cancel:hover { border-color: var(--ny); color: var(--ny); }
        .cammy-api-save { padding: 0.6rem 1.2rem; background: linear-gradient(135deg, #c9a84c, #e8c97a); border: none; color: #080600; font-weight: bold; border-radius: 6px; cursor: pointer; font-family: 'Cinzel', serif; font-size: 0.75rem; transition: all 0.2s; box-shadow: 0 4px 15px rgba(201,168,76,0.3); }
        .cammy-api-save:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(201,168,76,0.5); }
      `;
      document.head.appendChild(style);
    }

    var overlay = document.createElement('div');
    overlay.className = 'cammy-api-overlay';
    
    var box = document.createElement('div');
    box.className = 'cammy-api-box';
    
    var icon = document.createElement('div');
    icon.innerHTML = '🤖';
    icon.style.fontSize = '3rem';
    icon.style.marginBottom = '1rem';
    
    var title = document.createElement('div');
    title.className = 'cammy-api-title';
    title.innerText = 'Gemini API Key Required';
    
    var desc = document.createElement('div');
    desc.className = 'cammy-api-desc';
    desc.innerHTML = 'To use the AI Chatbot, please enter your Gemini API Key.<br><br>Get one for free at <a href="https://aistudio.google.com/app/apikey" target="_blank" class="cammy-api-link">Google AI Studio</a>.<br><br><i>It will only be saved locally in your browser for this session.</i>';
    
    var input = document.createElement('input');
    input.type = 'password';
    input.className = 'cammy-api-input';
    input.placeholder = 'Paste your API key here...';
    
    var btnRow = document.createElement('div');
    btnRow.className = 'cammy-api-btn-row';
    
    var cancelBtn = document.createElement('button');
    cancelBtn.className = 'cammy-api-cancel';
    cancelBtn.innerText = 'Cancel';
    cancelBtn.onclick = () => {
      document.body.removeChild(overlay);
      resolve(null);
    };
    
    var saveBtn = document.createElement('button');
    saveBtn.className = 'cammy-api-save';
    saveBtn.innerText = 'Save Key';
    saveBtn.onclick = () => {
      document.body.removeChild(overlay);
      resolve(input.value);
    };
    
    input.onkeydown = (e) => {
      if (e.key === 'Enter') saveBtn.click();
      if (e.key === 'Escape') cancelBtn.click();
    };
    
    btnRow.appendChild(cancelBtn);
    btnRow.appendChild(saveBtn);
    box.appendChild(icon);
    box.appendChild(title);
    box.appendChild(desc);
    box.appendChild(input);
    box.appendChild(btnRow);
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    
    input.focus();
  });
}

// ── REAL AI REPLY via Gemini ──
async function getCammyReply(userMsg) {
  if (GEMINI_API_KEY === "YOUR_GEMINI_API_KEY_HERE" || !GEMINI_API_KEY) {
    var userKey = await promptForApiKey();
    if (userKey) {
      GEMINI_API_KEY = userKey.trim();
      sessionStorage.setItem('GEMINI_API_KEY', GEMINI_API_KEY);
    } else {
      return "I need an API key to think! Please provide one to use this feature.";
    }
  }
  var kmNodes = typeof KM_GRAPH !== 'undefined'
    ? KM_GRAPH.nodes.map(n => n.label + ' (' + (['Foundation','Web Styling','Scripting','Advanced','Expert'][n.tier]) + ')').join(', ')
    : 'HTML Basics, CSS Basics, Semantic HTML, Forms, CSS Layout, CSS Mastery, JS Basics, DOM & Events, Functions, Arrays & Objects, Async JS, Algorithms, Data Structures, React';

  var systemPrompt = [
    "You are Cammy 💜, the AI learning companion inside LearnO — a gamified coding education web platform.",
    "Personality: warm, encouraging, enthusiastic, slightly playful, casual tone. Use emojis occasionally. Never be preachy or robotic.",

    // --- FULL SITE KNOWLEDGE ---
    "=== LEARNO PLATFORM OVERVIEW ===",
    "LearnO is a single-page web app with a black-and-gold luxury aesthetic (Cinzel Decorative font, gold glow effects). It teaches web development through gamification.",

    "=== NAVIGATION TABS ===",
    "HOME: Hero landing with stats counter (modules, puzzles, quiz questions). Buttons: Start Learning, Take a Quiz.",
    "LEARN: Linear lesson modules with expandable chapters. 10 chapters total across HTML, CSS, JavaScript, Algorithms, Data Structures, React.",
    "🗺️ MAP: Interactive Knowledge Graph (skill tree). 14 topic nodes connected by prerequisite edges. Nodes: " + kmNodes + ". States: locked (grey), available (gold), done (green), review-needed (red). Filters: All, Available, Completed, Locked, Review. Click a node to see details, prerequisites, and adaptive recommendations.",
    "QUIZ: Topic-based quizzes. 10 chapters, each with multiple questions. XP awarded per correct answer.",
    "PUZZLES: Code editor puzzles — write real code that runs in-browser. Big XP rewards.",
    "GAMES (6 total): Snake Quest (eat correct answers), Code Memory (flip card matching), Tower Build (drop blocks by answering), True/False Blitz (60s rapid fire), Fill the Blank (type missing code), Code Path (trace execution).",
    "RANKS: Leaderboard ranked by XP, live from Supabase database.",
    "BADGES: 14 achievement badges. Examples: First Blood (first perfect section), On Fire (5 streak), Diamond (1000 XP), Speed Demon (fast puzzle), and more.",

    "=== XP & PROGRESSION SYSTEM ===",
    "+20 XP per correct quiz answer. Bonus XP for perfect scores. Big XP for puzzles. Every 500 XP = level up. Higher levels unlock free avatars and exclusive nametag titles on the leaderboard.",

    "=== KNOWLEDGE MAP DETAILS ===",
    "The Knowledge Map is a graph-based learning engine. Nodes = topics. Edges = prerequisites (must complete node A before node B unlocks). Example: HTML Basics → CSS Basics, Semantic HTML, Forms. CSS Basics → CSS Layout, CSS Mastery. JS Basics → Functions, Arrays & Objects. Arrays → Algorithms, Data Structures. Async JS + Functions → React.",
    "Adaptive feature: if a student fails a topic, the map highlights prerequisite nodes and Cammy recommends reviewing them first.",

    "=== CHAPTERS & CURRICULUM ===",
    "Ch1: The Web Begins (HTML). Ch2: Style Your World (CSS). Ch3: JavaScript Awakens (JS basics). Ch4: Semantic Web (HTML5 semantics). Ch5: CSS Mastery (animations, variables, responsive). Ch6: JS Intermediate (functions, scope, closures). Ch7: Algorithms (sorting, Big-O). Ch8: Data Structures (stacks, queues, trees). Ch9: React (components, hooks). Ch10: Final Boss (mixed advanced).",

    "=== CAMMY (YOU) ===",
    "You are built into the floating chat button (bottom-right). You have quick-reply chips. You know the student's current stats.",
    "Student right now: Level " + (typeof ST !== 'undefined' ? ST.lv : '?') + ", " + (typeof ST !== 'undefined' ? ST.xp : '?') + " XP, " + (typeof CH_STATE !== 'undefined' ? CH_STATE.completedChapters.size : '?') + " chapters completed.",

    "=== HOW TO ANSWER ===",
    "Keep replies SHORT — 2-4 sentences max unless the user asks for a code explanation or step-by-step help.",
    "For coding questions: give concise code examples with brief explanation.",
    "Answer EXACTLY what was asked — don't mix up topics.",
    "If asked 'what can you do' or 'help': summarise the platform features and offer to explain any section.",
    "If asked about the Knowledge Map: explain it's a skill graph where nodes are topics, edges are prerequisites, and completing nodes unlocks new ones.",
  ].join('\n');

  cammyHistory.push({ role: 'user', content: userMsg });
  if (cammyHistory.length > 20) cammyHistory = cammyHistory.slice(-20);

  try {
    console.log('[Cammy] Calling Gemini API with key:', GEMINI_API_KEY.slice(0,12) + '...');
    var geminiContents = cammyHistory.map(function(m){
      return { role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: m.content }] };
    });
    var res = await fetch('https://generativelanguage.googleapis.com/v1beta/models/' + GEMINI_MODEL + ':generateContent?key=' + GEMINI_API_KEY, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: geminiContents,
        systemInstruction: { parts: [{ text: systemPrompt }] },
        generationConfig: { temperature: 0.75, maxOutputTokens: 220, thinkingConfig: { thinkingLevel: "low" } }
      })
    });
    console.log('[Cammy] HTTP status:', res.status);
    var data = await res.json();
    console.log('[Cammy] Raw response:', JSON.stringify(data).slice(0, 400));
    if (data.error) {
      console.error('[Cammy] Gemini API error:', data.error);
      return '\u26a0\ufe0f Cammy API error: ' + (data.error.message || JSON.stringify(data.error));
    }
    var reply = data.candidates && data.candidates[0] && data.candidates[0].content
      && data.candidates[0].content.parts && data.candidates[0].content.parts[0]
      ? data.candidates[0].content.parts[0].text.trim()
      : null;
    if (!reply) {
      console.warn('[Cammy] No reply in response:', data);
      return cammyKBReply(userMsg);
    }
    cammyHistory.push({ role: 'assistant', content: reply });
    return reply;
  } catch(e) {
    console.error('[Cammy] Fetch error:', e);
    return '\u26a0\ufe0f Cammy could not reach Gemini: ' + e.message;
  }
}

