function cammyKBReply(msg) {
  var m = msg.toLowerCase();
  for (var i = 0; i < CAMMY_KB.length; i++) {
    if (CAMMY_KB[i].keys.some(function(k){ return m.includes(k); })) {
      var r = CAMMY_KB[i].r;
      return r[Math.floor(Math.random() * r.length)];
    }
  }
  return "Great question! 🤔 I'm not sure about that one — but try checking the LEARN or QUIZ tab! And if you're stuck on something specific, just tell me what it is 💜";
}

// ── QUICK REPLIES ──
var QUICK_REPLIES = [
  '🏆 How does the leaderboard work?',
  '⚡ How do I earn XP?',
  '🏅 How do I unlock badges?',
  '🎮 What games are there?',
  '📚 Where should I start?',
];

function showQuickReplies() {
  var qr = document.getElementById('nova-quick');
  if (!qr) return;
  qr.innerHTML = '';
  var picks = [...QUICK_REPLIES].sort(function(){ return Math.random()-.5; }).slice(0,3);
  picks.forEach(function(q){
    var btn = document.createElement('button');
    btn.className = 'qr-btn';
    btn.textContent = q;
    btn.addEventListener('click', function(){ sendNova(q); });
    qr.appendChild(btn);
  });
}

// ── SEND MESSAGE ──
async function sendNova(text) {
  var inp = document.getElementById('nova-input');
  var msg = text || (inp ? inp.value.trim() : '');
  if (!msg) return;
  if (inp) inp.value = '';
  addCammyMsg(msg, 'user', false);
  var qr = document.getElementById('nova-quick');
  if (qr) qr.innerHTML = '';
  showTyping();
  var reply = await getCammyReply(msg);
  hideTyping();
  addCammyMsg(reply, 'bot', false);
  // NO TTS — no voice on replies
  showQuickReplies();
}

// ── TOGGLE CHAT WINDOW ──
function toggleNova() {
  var win = document.getElementById('nova-win');
  var notif = document.getElementById('nova-notif');
  if (!win) return;
  win.classList.toggle('open');
  if (notif) notif.style.display = 'none';
  if (!cammyOpened && win.classList.contains('open')) {
    cammyOpened = true;
    hideCammyPopup();
    setTimeout(function(){
      var greeting = "Heyy! I'm Cammy, your coding companion! 💜 I'm here to help you learn, answer questions, and guide you through LearnO. What can I help with today? 🎯";
      addCammyMsg(greeting, 'bot', false);
      cammyHistory.push({ role: 'assistant', content: greeting });
      showQuickReplies();
      // Play real voice greeting
      playCammyVoice('greeting');
    }, 400);
  }
}

