// Map chapter IDs to knowledge map node IDs
const KM_CHAPTER_MAP = {
  'ch1':'html-basics','ch2':'css-basics','ch3':'js-basics',
  'ch4':'html-semantic','ch5':'css-advanced','ch6':'js-functions',
  'ch7':'algorithms','ch8':'data-structures','ch9':'react'
};

let kmFilter_active = 'all';
let kmSelectedNode = null;
let kmViewBox = {x:0,y:0,w:900,h:560};
let kmDragging = false, kmDragStart = null;

function getKMNodeState(nodeId) {
  const fails = (typeof USER_PROFILE !== 'undefined' && USER_PROFILE.failedTopics) || [];
  const chapEntry = Object.entries(KM_CHAPTER_MAP).find(([,v]) => v === nodeId);
  if (chapEntry) {
    const ch = (typeof CHAPTERS !== 'undefined' ? CHAPTERS : []).find(c => c.id === chapEntry[0]);
    if (ch && ch.progress >= 100) return fails.includes(nodeId) ? 'review' : 'done';
  }
  if (nodeId === 'html-basics') return 'available';
  const prereqs = KM_GRAPH.edges.filter(e => e.to === nodeId).map(e => e.from);
  if (prereqs.length === 0) return 'available';
  const allDone = prereqs.every(p => getKMNodeState(p) === 'done');
  return allDone ? 'available' : 'locked';
}

function kmNodeColor(state) {
  return {
    done:'#27c93f', available:'#c9a84c',
    locked:'#2a2620', review:'#e05252'
  }[state] || '#2a2620';
}
function kmNodeGlow(state) {
  return {
    done:'drop-shadow(0 0 8px rgba(39,201,63,.8))',
    available:'drop-shadow(0 0 8px rgba(201,168,76,.7))',
    locked:'none',
    review:'drop-shadow(0 0 8px rgba(224,82,82,.8))'
  }[state];
}

function initKnowledgeMap() {
  kmRender();
  const svg = document.getElementById('km-svg');
  // Pan support
  svg.addEventListener('mousedown', kmOnDown);
  svg.addEventListener('mousemove', kmOnMove);
  svg.addEventListener('mouseup', kmOnUp);
  svg.addEventListener('mouseleave', kmOnUp);
  // Touch
  svg.addEventListener('touchstart', e => kmOnDown(e.touches[0]), {passive:true});
  svg.addEventListener('touchmove', e => { e.preventDefault(); kmOnMove(e.touches[0]); }, {passive:false});
  svg.addEventListener('touchend', kmOnUp);
}

function kmRender() {
  const svg = document.getElementById('km-svg');
  if (!svg) return;
  const filter = kmFilter_active;

  // Build SVG
  let defs = `<defs>
    <pattern id="km-bg-grid" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40,0 L0,0 0,40" fill="none" stroke="rgba(201,168,76,.04)" stroke-width="1"/></pattern>
    <radialGradient id="km-grd-done" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#3ef56d"/><stop offset="100%" stop-color="#1a8c35"/>
    </radialGradient>
    <radialGradient id="km-grd-avail" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#f0d080"/><stop offset="100%" stop-color="#9a6e10"/>
    </radialGradient>
    <radialGradient id="km-grd-lock" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#2f2b20"/><stop offset="100%" stop-color="#1a1700"/>
    </radialGradient>
    <radialGradient id="km-grd-review" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#ff7070"/><stop offset="100%" stop-color="#8c2020"/>
    </radialGradient>
    <filter id="km-glow-done"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
    <filter id="km-glow-avail"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
    <filter id="km-glow-review"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
    <marker id="km-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
      <path d="M0,0 L10,5 L0,10 z" fill="rgba(201,168,76,.35)"/>
    </marker>
    <marker id="km-arrow-active" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
      <path d="M0,0 L10,5 L0,10 z" fill="rgba(201,168,76,.9)"/>
    </marker>
  </defs>
  <rect width="900" height="560" fill="#060400"/>
  <rect width="900" height="560" fill="url(#km-bg-grid)" opacity=".4"/>`;

  // Grid pattern (moved into defs above)

  // Edges
  let edgesHTML = '';
  KM_GRAPH.edges.forEach(e => {
    const from = KM_GRAPH.nodes.find(n => n.id === e.from);
    const to = KM_GRAPH.nodes.find(n => n.id === e.to);
    if (!from || !to) return;
    const fromState = getKMNodeState(from.id);
    const toState = getKMNodeState(to.id);
    const matchesFilter = filter === 'all' ||
      (filter === 'done' && (fromState === 'done' || toState === 'done')) ||
      (filter === 'available' && (fromState === 'available' || toState === 'available')) ||
      (filter === 'locked' && (fromState === 'locked' || toState === 'locked'));
    const edgeOpacity = matchesFilter ? 1 : 0.07;
    const isActive = fromState !== 'locked';
    const isHighlight = kmSelectedNode && (e.from === kmSelectedNode || e.to === kmSelectedNode);
    const color = isHighlight ? 'rgba(201,168,76,.95)' : (isActive ? 'rgba(201,168,76,.3)' : 'rgba(255,255,255,.05)');
    const sw = isHighlight ? 2 : 1.5;
    const marker = isHighlight ? 'url(#km-arrow-active)' : (isActive ? 'url(#km-arrow)' : '');
    // Curved path
    const mx = (from.x + to.x) / 2;
    const my = (from.y + to.y) / 2 - 18;
    edgesHTML += `<path d="M${from.x},${from.y} Q${mx},${my} ${to.x},${to.y}" stroke="${color}" stroke-width="${sw}" fill="none" ${marker ? `marker-end="${marker}"` : ''} stroke-dasharray="${isActive ? 'none' : '5,4'}" opacity="${edgeOpacity}"/>`;
  });

  // Nodes
  let nodesHTML = '';
  KM_GRAPH.nodes.forEach(n => {
    const state = getKMNodeState(n.id);
    const nodeMatches = filter === 'all' ||
      (filter === 'done' && state === 'done') ||
      (filter === 'available' && state === 'available') ||
      (filter === 'locked' && state === 'locked') ||
      (filter === 'review' && state === 'review');
    const nodeOpacity = nodeMatches ? 1 : 0.1;
    const isSelected = kmSelectedNode === n.id;
    const grdId = {done:'km-grd-done',available:'km-grd-avail',locked:'km-grd-lock',review:'km-grd-review'}[state];
    const glowId = state !== 'locked' ? `km-glow-${state === 'available' ? 'avail' : state === 'review' ? 'review' : 'done'}` : '';
    const r = isSelected ? 32 : 28;
    const strokeColor = isSelected ? '#f0d080' : (state === 'locked' ? 'rgba(255,255,255,.08)' : kmNodeColor(state));
    const strokeW = isSelected ? 3 : 1.5;
    // Tier label
    const tierLabels = ['FOUNDATION','STYLE','SCRIPTING','ADVANCED','EXPERT'];
    nodesHTML += `
    <g class="km-node" data-id="${n.id}" style="cursor:${nodeMatches?'pointer':'default'};opacity:${nodeOpacity}" onclick="${nodeMatches?'kmSelectNode(\''+n.id+'\')':''}">
      <circle cx="${n.x}" cy="${n.y}" r="${r+8}" fill="transparent"/>
      <circle cx="${n.x}" cy="${n.y}" r="${r}" fill="url(#${grdId})" stroke="${strokeColor}" stroke-width="${strokeW}" ${glowId ? `filter="url(#${glowId})"` : ''}/>
      ${isSelected ? `<circle cx="${n.x}" cy="${n.y}" r="${r+5}" fill="none" stroke="rgba(240,208,128,.3)" stroke-width="1.5" stroke-dasharray="4,3"/>` : ''}
      <text x="${n.x}" y="${n.y + 5}" text-anchor="middle" dominant-baseline="central" font-size="16">${n.icon}</text>
      <text x="${n.x}" y="${n.y + r + 14}" text-anchor="middle" font-family="Cinzel,serif" font-size="8.5" fill="${state === 'locked' ? 'rgba(255,255,255,.25)' : '#f0d080'}" letter-spacing="0.5">${n.label.toUpperCase()}</text>
      ${state === 'done' ? `<circle cx="${n.x+r-4}" cy="${n.y-r+4}" r="8" fill="#27c93f" stroke="#060400" stroke-width="1.5"/>
        <text x="${n.x+r-4}" y="${n.y-r+8}" text-anchor="middle" font-size="10" font-weight="900" fill="#060400">&#10003;</text>` : ''}
      ${state === 'review' ? `<circle cx="${n.x+r-4}" cy="${n.y-r+4}" r="8" fill="#e05252" stroke="#060400" stroke-width="1.5"/>
        <text x="${n.x+r-4}" y="${n.y-r+8}" text-anchor="middle" font-size="11" font-weight="900" fill="#fff">!</text>` : ''}
      ${state === 'locked' ? `<circle cx="${n.x+r-4}" cy="${n.y-r+4}" r="8" fill="#1a1700" stroke="rgba(255,255,255,.15)" stroke-width="1.5"/>
        <text x="${n.x+r-4}" y="${n.y-r+8}" text-anchor="middle" font-size="10" fill="rgba(255,255,255,.3)">&#128274;</text>` : ''}
    </g>`;
  });

  // Tier separators
  let tiersHTML = '';
  const tierYs = [30, 145, 265, 385, 480];
  const tierNames = ['FOUNDATION','WEB STYLING','SCRIPTING','ADVANCED','EXPERT'];
  tierYs.forEach((y, i) => {
    tiersHTML += `<line x1="30" y1="${y}" x2="870" y2="${y}" stroke="rgba(201,168,76,.06)" stroke-width="1" stroke-dasharray="4,8"/>`;
    tiersHTML += `<text x="18" y="${y+4}" font-family="Cinzel,serif" font-size="6.5" fill="rgba(201,168,76,.25)" letter-spacing="1" writing-mode="horizontal-tb">${tierNames[i]}</text>`;
  });

  svg.innerHTML = defs + tiersHTML + edgesHTML + nodesHTML;
}

function kmSelectNode(id) {
  kmSelectedNode = id;
  kmRender();
  const node = KM_GRAPH.nodes.find(n => n.id === id);
  if (!node) return;
  const state = getKMNodeState(id);
  const panel = document.getElementById('km-detail-panel');
  panel.className = 'show';

  document.getElementById('km-dp-icon').textContent = node.icon;
  document.getElementById('km-dp-title').textContent = node.label;
  document.getElementById('km-dp-sub').textContent = ['Foundation','Web Styling','Scripting','Advanced','Expert'][node.tier] + ' · Tier ' + (node.tier+1);
  document.getElementById('km-dp-body').textContent = node.details;

  // Prerequisites
  const prereqs = KM_GRAPH.edges.filter(e => e.to === id).map(e => e.from);
  const prereqWrap = document.getElementById('km-dp-prereq-wrap');
  if (prereqs.length) {
    prereqWrap.style.display = 'block';
    document.getElementById('km-dp-prereqs').innerHTML = prereqs.map(p => {
      const pn = KM_GRAPH.nodes.find(n => n.id === p);
      const ps = getKMNodeState(p);
      const done = ps === 'done' || ps === 'available';
      return `<span class="km-prereq-tag ${done ? 'km-prereq-done' : 'km-prereq-miss'}">${pn ? pn.icon+' '+pn.label : p} ${done ? '✓' : '✗'}</span>`;
    }).join('');
  } else {
    prereqWrap.style.display = 'none';
  }

  // Adaptive recommendation
  const recBox = document.getElementById('km-rec-box');
  const recText = document.getElementById('km-rec-text');
  const fails = (typeof USER_PROFILE !== 'undefined' && USER_PROFILE.failedTopics) || [];
  if (state === 'review' || fails.includes(id)) {
    recBox.style.display = 'block';
    const missingPrereqs = prereqs.filter(p => getKMNodeState(p) === 'locked');
    if (missingPrereqs.length) {
      const names = missingPrereqs.map(p => KM_GRAPH.nodes.find(n => n.id === p)?.label || p).join(', ');
      recText.textContent = `You struggled here. We recommend revisiting: ${names} first to strengthen your foundation.`;
    } else {
      recText.textContent = `This topic needs more practice. Try re-reading the lesson and retaking the quiz to reinforce your understanding.`;
    }
  } else if (state === 'locked') {
    recBox.style.display = 'block';
    const missing = prereqs.filter(p => getKMNodeState(p) === 'locked');
    const names = missing.map(p => KM_GRAPH.nodes.find(n => n.id === p)?.label || p).join(', ');
    recText.textContent = `Complete ${names || 'the prerequisites'} first to unlock this topic. Stay on the path!`;
  } else {
    recBox.style.display = 'none';
  }

  // Actions
  const actions = document.getElementById('km-dp-actions');
  const chapEntry = Object.entries(KM_CHAPTER_MAP).find(([,v]) => v === id);
  let html = '';
  if (chapEntry && state !== 'locked') {
    html += `<button class="br" onclick="gS('learn')">📖 Open Lesson</button>`;
    html += `<button class="bh" onclick="gS('quiz')">⚡ Take Quiz</button>`;
  }
  // Show what this unlocks
  const unlocks = KM_GRAPH.edges.filter(e => e.from === id).map(e => e.to);
  if (unlocks.length && state === 'done') {
    const unlockedNodes = unlocks.map(u => KM_GRAPH.nodes.find(n => n.id === u)?.label).filter(Boolean).join(', ');
    html += `<div style="width:100%;font-size:.72rem;color:var(--td);margin-top:.3rem">🔓 Unlocks: <span style="color:var(--ny)">${unlockedNodes}</span></div>`;
  }
  actions.innerHTML = html;
}

function kmFilter(f) {
  kmFilter_active = f;
  document.querySelectorAll('.km-ctrl-btn').forEach(b => b.classList.remove('active'));
  const btn = document.getElementById('km-filter-'+f);
  if (btn) btn.classList.add('active');
  kmRender();
}

function kmResetView() {
  kmSelectedNode = null;
  kmFilter_active = 'all';
  document.querySelectorAll('.km-ctrl-btn').forEach(b => b.classList.remove('active'));
  const all = document.getElementById('km-filter-all');
  if (all) all.classList.add('active');
  document.getElementById('km-detail-panel').className = '';
  kmRender();
}

// Pan
function kmOnDown(e) {
  kmDragging = true;
  kmDragStart = {x: e.clientX, y: e.clientY, vx: kmViewBox.x, vy: kmViewBox.y};
  document.getElementById('km-svg').classList.add('dragging');
}
function kmOnMove(e) {
  if (!kmDragging || !kmDragStart) return;
  const dx = (kmDragStart.x - e.clientX) * (kmViewBox.w / document.getElementById('km-svg').clientWidth);
  const dy = (kmDragStart.y - e.clientY) * (kmViewBox.h / document.getElementById('km-svg').clientHeight);
  kmViewBox.x = Math.max(-100, Math.min(200, kmDragStart.vx + dx));
  kmViewBox.y = Math.max(-50, Math.min(100, kmDragStart.vy + dy));
  document.getElementById('km-svg').setAttribute('viewBox', `${kmViewBox.x} ${kmViewBox.y} ${kmViewBox.w} ${kmViewBox.h}`);
}
function kmOnUp() {
  kmDragging = false;
  const svg = document.getElementById('km-svg');
  if (svg) svg.classList.remove('dragging');
}

// Hook: mark failed topic for adaptive recs
function kmMarkFailed(nodeId) {
  if (typeof USER_PROFILE === 'undefined') return;
  if (!USER_PROFILE.failedTopics) USER_PROFILE.failedTopics = [];
  if (!USER_PROFILE.failedTopics.includes(nodeId)) {
    USER_PROFILE.failedTopics.push(nodeId);
  }
}

// ═══════════════════════════════════════════════════════
// VAULT — File Library
// ═══════════════════════════════════════════════════════
var VAULT_FILES = JSON.parse(localStorage.getItem('learno-vault') || '[]');
var vaultCurrentFilter = 'all';
var vaultPreviewFile = null;

function vaultSave() {
  // Save metadata only (not base64 — stored per-file key)
  var meta = VAULT_FILES.map(function(f){ return {id:f.id,name:f.name,type:f.type,size:f.size,date:f.date}; });
  localStorage.setItem('learno-vault', JSON.stringify(meta));
}

function vaultGetFileData(id) {
  return localStorage.getItem('learno-vault-file-' + id);
}

function vaultStoreFileData(id, data) {
  try {
    localStorage.setItem('learno-vault-file-' + id, data);
    return true;
  } catch(e) {
    return false;
  }
}

function vaultDeleteFileData(id) {
  localStorage.removeItem('learno-vault-file-' + id);
}

function vaultGetType(filename) {
  var ext = filename.split('.').pop().toLowerCase();
  if (ext === 'pdf') return 'pdf';
  if (['jpg','jpeg','png','gif','webp','bmp','svg'].includes(ext)) return 'image';
  if (['doc','docx'].includes(ext)) return 'doc';
  return 'other';
}

function vaultTypeIcon(type) {
  if (type === 'pdf') return '📄';
  if (type === 'image') return '🖼️';
  if (type === 'doc') return '📝';
  return '📎';
}

function vaultFormatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1048576) return (bytes/1024).toFixed(1) + ' KB';
  return (bytes/1048576).toFixed(1) + ' MB';
}

function vaultAddFiles(files) {
  var added = 0;
  Array.from(files).forEach(function(file) {
    var type = vaultGetType(file.name);
    if (type === 'other') return;

    var reader = new FileReader();
    reader.onload = function(e) {
      var id = 'v' + Date.now() + Math.random().toString(36).slice(2,6);
      var stored = vaultStoreFileData(id, e.target.result);
      if (!stored) {
        alert('Storage full — file too large or too many files stored.');
        return;
      }
      VAULT_FILES.push({ id: id, name: file.name, type: type, size: file.size, date: new Date().toLocaleDateString() });
      vaultSave();
      vaultRenderWithAI();
    };
    reader.readAsDataURL(file);
    added++;
  });
  if (added === 0) alert('Only PDF, image (JPG/PNG/GIF), and Word (DOC/DOCX) files are supported.');
}

function vaultRender() {
  var grid = document.getElementById('vault-grid');
  var empty = document.getElementById('vault-empty');
  if (!grid) return;

  var filtered = VAULT_FILES.filter(function(f){
    if (vaultCurrentFilter === 'all') return true;
    return f.type === vaultCurrentFilter;
  });

  // Remove old cards
  Array.from(grid.children).forEach(function(el){
    if (!el.classList.contains('vault-empty')) el.remove();
  });

  if (filtered.length === 0) {
    empty.style.display = 'block';
    return;
  }
  empty.style.display = 'none';

  filtered.forEach(function(f) {
    var card = document.createElement('div');
    card.className = 'vault-card';
    card.setAttribute('data-id', f.id);
    card.setAttribute('data-type', f.type);

    var thumbHTML = '';
    if (f.type === 'image') {
      var data = vaultGetFileData(f.id);
      if (data) {
        thumbHTML = '<img src="' + data + '" alt="' + f.name + '" loading="lazy">';
      } else {
        thumbHTML = '<span class="vault-icon">' + vaultTypeIcon(f.type) + '</span>';
      }
    } else {
      thumbHTML = '<span class="vault-icon">' + vaultTypeIcon(f.type) + '</span>';
    }

    var typeBadge = '<span class="vault-card-type vault-type-' + f.type + '">' + f.type.toUpperCase() + '</span>';

    card.innerHTML =
      '<div class="vault-card-thumb">' + thumbHTML + '</div>' +
      '<button class="vault-card-del" onclick="vaultDelete(event,\'' + f.id + '\')" title="Delete">✕</button>' +
      '<div class="vault-card-info">' +
        '<div class="vault-card-name" title="' + f.name + '">' + f.name + '</div>' +
        '<div class="vault-card-meta">' +
          typeBadge +
          '<span>' + vaultFormatSize(f.size) + '</span>' +
        '</div>' +
      '</div>';

    card.addEventListener('click', function(e){
      if (e.target.classList.contains('vault-card-del')) return;
      vaultOpenPreview(f.id);
    });

    grid.appendChild(card);
  });
}

function vaultDelete(e, id) {
  e.stopPropagation();
  if (!confirm('Delete this file from your vault?')) return;
  VAULT_FILES = VAULT_FILES.filter(function(f){ return f.id !== id; });
  vaultDeleteFileData(id);
  vaultSave();
  vaultRenderWithAI();
}

function vaultFilter(type) {
  vaultCurrentFilter = type;
  document.querySelectorAll('.vault-filter-btn').forEach(function(b){ b.classList.remove('active'); });
  var btn = document.getElementById('vf-' + type);
  if (btn) btn.classList.add('active');
  vaultRender();
}

function vaultOpenPreview(id) {
  var f = VAULT_FILES.find(function(x){ return x.id === id; });
  if (!f) return;
  vaultPreviewFile = f;
  var data = vaultGetFileData(id);
  document.getElementById('vault-preview-name').textContent = f.name;

  var body = document.getElementById('vault-preview-body');
  body.innerHTML = '';

  if (!data) {
    body.innerHTML = '<div class="vault-doc-preview"><div style="font-size:3rem">⚠️</div><div style="color:var(--td);margin-top:.5rem">File data not found</div></div>';
  } else if (f.type === 'image') {
    var img = document.createElement('img');
    img.src = data;
    img.alt = f.name;
    body.appendChild(img);
  } else if (f.type === 'pdf') {
    var iframe = document.createElement('iframe');
    iframe.src = data;
    iframe.title = f.name;
    body.appendChild(iframe);
  } else {
    // Word doc — can't preview in browser, show message
    body.innerHTML =
      '<div class="vault-doc-preview">' +
        '<div style="font-size:4rem;margin-bottom:1rem">📝</div>' +
        '<div style="font-family:Cinzel,serif;font-size:.85rem;color:var(--ny);margin-bottom:.5rem">' + f.name + '</div>' +
        '<div style="font-size:.82rem;color:var(--td);margin-bottom:1.2rem">Word documents cannot be previewed in the browser.<br>Click Download to open it.</div>' +
      '</div>';
  }

  document.getElementById('vault-preview-modal').classList.remove('hid');
}

function closeVaultPreview() {
  document.getElementById('vault-preview-modal').classList.add('hid');
  document.getElementById('vault-preview-body').innerHTML = '';
  vaultPreviewFile = null;
}

function downloadVaultFile() {
  if (!vaultPreviewFile) return;
  var data = vaultGetFileData(vaultPreviewFile.id);
  if (!data) return;
  var a = document.createElement('a');
  a.href = data;
  a.download = vaultPreviewFile.name;
  a.click();
}

function vaultInitDragDrop() {
  var zone = document.getElementById('vault-drop-zone');
  if (!zone) return;

  zone.addEventListener('dragover', function(e){
    e.preventDefault();
    zone.classList.add('dragging');
  });
  zone.addEventListener('dragleave', function(){
    zone.classList.remove('dragging');
  });
  zone.addEventListener('drop', function(e){
    e.preventDefault();
    zone.classList.remove('dragging');
    vaultAddFiles(e.dataTransfer.files);
  });
  zone.addEventListener('click', function(e){
    if (e.target.classList.contains('vault-browse-btn')) return;
    document.getElementById('vault-file-input').click();
  });

  document.getElementById('vault-file-input').addEventListener('change', function(){
    vaultAddFiles(this.files);
    this.value = '';
  });
}

// Close preview on backdrop click
document.addEventListener('click', function(e){
  if (e.target.id === 'vault-preview-modal') closeVaultPreview();
});

// Init vault when screen is opened (lazy)
var _vaultInited = false;
function initVaultOnFirstOpen() {
  if (_vaultInited) return;
  _vaultInited = true;
  var meta = JSON.parse(localStorage.getItem('learno-vault') || '[]');
  VAULT_FILES = meta;
  syncCustomChapters();
  vaultRenderWithAI();
  vaultInitDragDrop();
}


// ═══════════════════════════════════════════════════════
// VAULT AI — Generate Chapter from Uploaded File
// ═══════════════════════════════════════════════════════

var CUSTOM_CHAPTERS = JSON.parse(localStorage.getItem('learno-custom-chapters') || '[]');

function saveCustomChapters() {
  localStorage.setItem('learno-custom-chapters', JSON.stringify(CUSTOM_CHAPTERS));
}

// Inject custom chapters into CHAPTERS array (without duplicates)
function syncCustomChapters() {
  CUSTOM_CHAPTERS.forEach(function(cc) {
    var exists = CHAPTERS.find(function(c){ return c.id === cc.id; });
    if (!exists) {
      cc.unlocked = true;
      CHAPTERS.push(cc);
    }
  });
}

// Extract text from a file (image uses Cammy vision, PDF/doc uses base64 text extraction hint)
async function vaultExtractText(file, dataUrl) {
  // For images: send to Claude with vision
  if (file.type === 'image') {
    return { type: 'image', dataUrl: dataUrl, mimeType: getMimeType(file.name) };
  }
  // For PDF and DOC: we send base64 as document
  if (file.type === 'pdf') {
    return { type: 'pdf', dataUrl: dataUrl };
  }
  if (file.type === 'doc') {
    return { type: 'doc', dataUrl: dataUrl };
  }
  return null;
}

function getMimeType(filename) {
  var ext = filename.split('.').pop().toLowerCase();
  var map = { jpg:'image/jpeg', jpeg:'image/jpeg', png:'image/png', gif:'image/gif', webp:'image/webp', bmp:'image/bmp', svg:'image/svg+xml' };
  return map[ext] || 'image/png';
}

async function generateChapterFromFile(vaultFileObj) {
  var dataUrl = vaultGetFileData(vaultFileObj.id);
  if (!dataUrl) { alert('File data not found in vault.'); return; }

  // Show loading UI in vault
  showVaultGenerating(vaultFileObj.name);

  var base64Data = dataUrl.split(',')[1];
  var mimeType = '';
  if (vaultFileObj.type === 'image') mimeType = getMimeType(vaultFileObj.name);
  else if (vaultFileObj.type === 'pdf') mimeType = 'application/pdf';
  else mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';

  var systemPrompt = [
    "You are an expert educational content creator for LearnO — a gamified learning platform.",
    "A user has uploaded a document. Your job is to read it and create a structured learning chapter from its content.",
    "",
    "Return ONLY a valid JSON object (no markdown, no backticks, no extra text) with this exact structure:",
    "{",
    '  "title": "Chapter Title (short, max 4 words)",',
    '  "icon": "one relevant emoji",',
    '  "desc": "One sentence description of what this chapter covers",',
    '  "paragraphs": [',
    "    {",
    '      "title": "Section Title",',
    '      "text": "Detailed explanation of this topic from the document. 3-5 sentences. Use <strong> for key terms and <code> for technical terms. Write as a teacher explaining to a student.",',
    '      "quizzes": [',
    "        {",
    '          "q": "Question about this section?",',
    '          "opts": ["Option A", "Option B", "Option C", "Option D"],',
    '          "ans": 0,',
    '          "exp": "Explanation of why the correct answer is right."',
    "        },",
    "        { same format, 2nd question },",
    "        { same format, 3rd question }",
    "      ]",
    "    },",
    "    { 2nd section, same format },",
    "    { 3rd section, same format }",
    "  ]",
    "}",
    "",
    "Rules:",
    "- Create exactly 3 paragraphs (sections), each with exactly 3 quiz questions",
    "- ans is the INDEX (0-3) of the correct answer in opts array",
    "- Base ALL content ONLY on what is in the uploaded document",
    "- Make questions genuinely educational and specific to the document content",
    "- Return ONLY the JSON — no explanation, no markdown fences"
  ].join('\n');

  // Build parts for Gemini (supports inline images and PDFs directly)
  var geminiParts = [];

  if (vaultFileObj.type === 'image') {
    geminiParts.push({ inline_data: { mime_type: mimeType, data: base64Data } });
    geminiParts.push({ text: 'Please create a learning chapter from the content in this image.' });
  } else if (vaultFileObj.type === 'pdf') {
    geminiParts.push({ inline_data: { mime_type: 'application/pdf', data: base64Data } });
    geminiParts.push({ text: 'Please create a learning chapter from the content in this PDF document.' });
  } else {
    // Word doc — send as text hint since browser can't parse docx
    geminiParts.push({ text: 'The user uploaded a Word document called "' + vaultFileObj.name + '". I cannot read it directly. Please create a placeholder chapter with the title based on the filename, and note in the text that the user should verify the content matches their document. Make the sections about general study skills instead.' });
  }

  try {
    var response = await fetch('https://generativelanguage.googleapis.com/v1beta/models/' + GEMINI_MODEL + ':generateContent?key=' + GEMINI_API_KEY, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ role: 'user', parts: geminiParts }],
        systemInstruction: { parts: [{ text: systemPrompt }] },
        generationConfig: { temperature: 0.4, maxOutputTokens: 2000 }
      })
    });

    var data = await response.json();
    if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));

    var raw = (data.candidates && data.candidates[0] && data.candidates[0].content
      && data.candidates[0].content.parts && data.candidates[0].content.parts[0])
      ? data.candidates[0].content.parts[0].text
      : '';
    // Strip any markdown fences just in case
    raw = raw.replace(/```json/g,'').replace(/```/g,'').trim();

    var chapterData;
    try {
      chapterData = JSON.parse(raw);
    } catch(e) {
      throw new Error('AI returned invalid JSON. Please try again.');
    }

    // Build full chapter object
    var chapId = 'custom-' + vaultFileObj.id;
    var chapNum = CHAPTERS.length + 1;
    var newChapter = {
      id: chapId,
      num: chapNum,
      title: chapterData.title || vaultFileObj.name,
      icon: chapterData.icon || '📖',
      level: 'custom',
      col: 'cy',
      desc: chapterData.desc || 'Generated from your uploaded file.',
      unlocked: true,
      sourceFile: vaultFileObj.name,
      paragraphs: chapterData.paragraphs.map(function(p, pi) {
        return {
          id: chapId + 'p' + (pi+1),
          title: p.title,
          text: p.text,
          quizzes: p.quizzes.map(function(q) {
            return { q: q.q, opts: q.opts, ans: q.ans, exp: q.exp };
          })
        };
      })
    };

    // Save and sync
    CUSTOM_CHAPTERS.push(newChapter);
    saveCustomChapters();
    syncCustomChapters();

    // Also register quizzes in CHAPTER_QQ
    newChapter.paragraphs.forEach(function(p) {
      CHAPTER_QQ[newChapter.id] = CHAPTER_QQ[newChapter.id] || [];
      p.quizzes.forEach(function(q) { CHAPTER_QQ[newChapter.id].push(q); });
    });

    hideVaultGenerating();
    showVaultSuccess(newChapter, vaultFileObj);

  } catch(e) {
    hideVaultGenerating();
    alert('Generation failed: ' + e.message);
  }
}

function showVaultGenerating(filename) {
  var existing = document.getElementById('vault-gen-overlay');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'vault-gen-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:7000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(8px);animation:fi .2s ease;';
  overlay.innerHTML =
    '<div style="text-align:center;max-width:360px;padding:2.5rem;">' +
      '<div style="font-size:3.5rem;margin-bottom:1rem;animation:gc-bob 1.5s ease-in-out infinite">🤖</div>' +
      '<div style="font-family:Cinzel Decorative,serif;font-size:1.1rem;color:#f0d080;margin-bottom:.5rem;">Generating Chapter...</div>' +
      '<div style="font-size:.82rem;color:#9a8660;line-height:1.7;margin-bottom:1.5rem;">Cammy is reading <strong style="color:#f0d080">' + filename + '</strong><br>and creating your lesson, sections & quizzes.</div>' +
      '<div style="width:200px;height:4px;background:rgba(201,168,76,.15);border-radius:99px;margin:0 auto;overflow:hidden;">' +
        '<div style="height:100%;background:linear-gradient(90deg,#c9a84c,#f0d080);border-radius:99px;animation:vault-progress 2.5s ease-in-out infinite;"></div>' +
      '</div>' +
    '</div>' +
    '<style>@keyframes vault-progress{0%{width:0%;margin-left:0}50%{width:80%;margin-left:0}100%{width:0%;margin-left:100%}}</style>';
  document.body.appendChild(overlay);
}

function hideVaultGenerating() {
  var overlay = document.getElementById('vault-gen-overlay');
  if (overlay) overlay.remove();
}

function showVaultSuccess(chapter, vaultFile) {
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:7000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(8px);animation:fi .2s ease;';
  overlay.innerHTML = `
    <div style="text-align:center;max-width:400px;padding:2.5rem;background:#0e0b04;border:1px solid rgba(201,168,76,.35);border-radius:14px;box-shadow:0 0 60px rgba(201,168,76,.15);">
      <div style="font-size:3rem;margin-bottom:.8rem;">&#x1F389;</div>
      <div style="font-family:Cinzel Decorative,serif;font-size:1.1rem;color:#f0d080;margin-bottom:.4rem;">Chapter Created!</div>
      <div style="font-size:.82rem;color:#9a8660;margin-bottom:1.2rem;">Your new chapter <strong style="color:#f0d080">${chapter.icon} ${chapter.title}</strong> is ready with 3 sections and 9 quiz questions.</div>
      <div style="display:flex;gap:.7rem;justify-content:center;flex-wrap:wrap;">
        <button onclick="this.closest('div[style]').parentElement.remove();gS('learn');" style="font-family:Cinzel Decorative,serif;font-size:.72rem;font-weight:700;letter-spacing:1px;padding:.6rem 1.5rem;background:linear-gradient(135deg,#c9a84c,#f0d080);border:none;border-radius:6px;color:#080600;cursor:pointer;">&#x1F4D6; Open in Learn</button>
        <button onclick="this.closest('div[style]').parentElement.remove();gS('quiz');" style="font-family:Cinzel,serif;font-size:.7rem;padding:.6rem 1.2rem;background:none;border:1px solid rgba(201,168,76,.45);color:#f0d080;border-radius:6px;cursor:pointer;">&#x26A1; Take Quiz</button>
        <button onclick="this.closest('div[style]').parentElement.remove();" style="font-family:Cinzel,serif;font-size:.7rem;padding:.6rem 1.2rem;background:none;border:1px solid rgba(255,255,255,.1);color:#9a8660;border-radius:6px;cursor:pointer;">Stay in Vault</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);

  // Re-render vault to reflect the new chapter badge on the card
  vaultRender();
}

// Show "generate" button on vault cards
function vaultRenderWithAI() {
  vaultRender();
  // Augment each card with a Generate Chapter button
  setTimeout(function() {
    VAULT_FILES.forEach(function(f) {
      var card = document.querySelector('[data-id="' + f.id + '"]');
      if (!card) return;

      // Check if chapter already generated
      var alreadyMade = CUSTOM_CHAPTERS.find(function(cc){ return cc.id === 'custom-' + f.id; });

      var actionBar = document.createElement('div');
      actionBar.style.cssText = 'padding:.5rem .8rem .8rem;border-top:1px solid rgba(201,168,76,.1);';
      if (alreadyMade) {
        actionBar.innerHTML = `<div style="display:flex;gap:.4rem;">
          <button onclick="gS('learn')" style="flex:1;font-family:Cinzel,serif;font-size:.58rem;letter-spacing:.5px;padding:.35rem .4rem;background:rgba(39,201,63,.1);border:1px solid rgba(39,201,63,.3);color:#7ae87c;border-radius:6px;cursor:pointer;">&#x2705; Open Chapter</button>
          <button onclick="deleteVaultChapter('${f.id}')" style="font-family:Cinzel,serif;font-size:.58rem;padding:.35rem .5rem;background:rgba(224,82,82,.08);border:1px solid rgba(224,82,82,.25);color:#e88f8f;border-radius:6px;cursor:pointer;" title="Remove generated chapter">&#x1F5D1;</button>
          </div>`;
      } else {
        actionBar.innerHTML = `<button onclick="generateChapterFromFile(VAULT_FILES.find(function(x){return x.id==='${f.id}'}))" style="width:100%;font-family:Cinzel Decorative,serif;font-size:.58rem;letter-spacing:.5px;padding:.38rem .5rem;background:linear-gradient(135deg,rgba(201,168,76,.15),rgba(184,146,42,.1));border:1px solid rgba(201,168,76,.35);color:#f0d080;border-radius:6px;cursor:pointer;transition:all .2s;" onmouseover="this.style.background='rgba(201,168,76,.25)'" onmouseout="this.style.background='linear-gradient(135deg,rgba(201,168,76,.15),rgba(184,146,42,.1))'">&#x1F916; Generate Chapter</button>`;
      }
      card.appendChild(actionBar);
    });
  }, 50);
}


function deleteVaultChapter(fileId) {
  if (!confirm('Remove the generated chapter for this file? The file stays in the vault.')) return;
  var chapId = 'custom-' + fileId;
  CUSTOM_CHAPTERS = CUSTOM_CHAPTERS.filter(function(c){ return c.id !== chapId; });
  saveCustomChapters();
  // Remove from CHAPTERS array
  var idx = CHAPTERS.findIndex(function(c){ return c.id === chapId; });
  if (idx !== -1) CHAPTERS.splice(idx, 1);
  delete CHAPTER_QQ[chapId];
  _vaultInited = false;
  initVaultOnFirstOpen();
}

